{{ config(materialized='semantic_view', schema='SEMANTIC') }}

TABLES(
    people AS {{ ref('fct_mhsds_person_summary') }}
        PRIMARY KEY (person_id) COMMENT = 'Summary of the MHSDS evidence available for each identifiable person. Each row is one MHSDS person ID, including people recorded only in clinical, legal-status or other modelled evidence. Use it to select cohorts and compare recorded referrals, contacts, diagnoses, current caseload and inpatient evidence. The as_of_date is the latest accepted dataset period; individual providers can be older. Recent-contact measures exclude dates after that date. Diagnosis counts count records, not clinically current conditions. No qualifying evidence gives zero or false; missing clinical values and patient indicators remain null. National ID changes can split one person''s history across rows.',
    referrals AS {{ ref('fct_mhsds_referral_summary') }}
        PRIMARY KEY (source_record_id) COMMENT = 'Care and access measures for each recorded referral. Each row is one latest service request, with counts of contacts, submitted indirect activity, recorded hospital spells and team relationships. Referrals with missing person details remain included. Records that cannot be linked to a referral remain available in their own detailed tables. The measures are calculated before they are joined, so several contacts and teams do not multiply each other. Time to first attendance describes recorded evidence; it is not a national waiting-time compliance measure.',
    contacts AS {{ ref('fct_mhsds_care_contact') }}
        PRIMARY KEY (source_record_id) COMMENT = 'Recorded patient contacts, including attended appointments, non-attendance and cancellations. Each row is one referral/contact pair using its latest accepted version. Cancelled contacts retain their scheduled date; pre-1901 missing-date markers are null. Contacts remain when their referral is absent. Team details come from the contact''s submission: an explicit contact team takes precedence, with the primary referral team used for version 6 records without one. Later changes to a referral''s person ID do not reassign the contact.',
    spells AS {{ ref('fct_mhsds_hospital_provider_spell') }}
        PRIMARY KEY (source_record_id) COMMENT = 'Admissions and discharges as recorded by providers. Each row is the latest submitted version of one provider-qualified hospital spell. A missing discharge date means no discharge was recorded; it does not prove current occupancy. This table retains recorded spells before overlap removal or inferred closure, and does not apply currency or costing rules. If a provider reuses a spell identifier, the earlier record is treated as a version of that spell rather than a separate admission.',
    occupancy AS {{ ref('fct_mhsds_inpatient_occupancy') }}
        PRIMARY KEY (occupancy_interval_id) COMMENT = 'Hospital spells interpreted as periods of inpatient occupancy under the shared overlap and recency rules. Each row is one retained interval, including records without a person or cross-system patient match. Recorded discharge and inferred end dates remain separate, with the reason for the inferred end and the dates of supporting evidence. Overlapping and stale spells are handled upstream, so counts can differ from the recorded hospital-spell table.',
    diagnoses AS {{ ref('fct_mhsds_diagnosis') }}
        PRIMARY KEY (diagnosis_record_id) COMMENT = 'Previous, provisional, primary and secondary diagnoses recorded in MHSDS. Each row is one retained diagnosis evidence item from the shared clinical-record table. Includes records with missing dates, descriptions, person details or other links. Repeated versions of the same fully identified item are reduced to the latest accepted version; different codes and people remain separate. Use this table to describe recorded diagnosis evidence, not to decide which diagnosis is clinically current.',
    assessments AS {{ ref('fct_mhsds_assessment_observation') }}
        PRIMARY KEY (assessment_observation_id) COMMENT = 'Responses and scores recorded in referral, activity and historical clustering assessments. Each row is an accepted MHS606 or MHS607 response occurrence, or the latest MHS802 response for a provider, source assessment and concept. Repeated monthly clustering submissions are treated as versions, with their source counts retained. Missing links and unknown responses remain visible. A row can be one question or dimension rather than a whole questionnaire. Use the instance and score-change tables for response groups and comparisons over time.',
    legal_status AS {{ ref('fct_mhsds_mental_health_act_period') }}
        PRIMARY KEY (mental_health_act_period_id) COMMENT = 'Recorded periods of Mental Health Act legal status. Each row is one period using its latest accepted version, including unknown codes and missing person details. A period counts as current detention when its code is classified as detention, it has no recorded end, it is unexpired at the dataset observation date, and it was last reported within two calendar months of that date. These are the existing project rules. Concurrent community orders are not reclassified by this table.',
    submissions AS {{ ref('dq_mhsds_provider_submission') }}
        PRIMARY KEY (provider_organisation_code, reporting_period_end_date) COMMENT = 'Submission dates and record counts for each provider and accepted reporting period. Use this table to check how recent a provider''s evidence is before comparing activity or caseload. Referral, contact and patient counts describe submitted rows before selecting the latest version of each record. A missing period has no row. A zero count in one section does not by itself mean the submission failed or was incomplete.',
    demographics AS {{ ref('dim_mhsds_person_provider_period') }}
        PRIMARY KEY (person_provider_period_id) COMMENT = 'Demographic details recorded for a person by a provider in a reporting period. Each row is one identifiable person, provider and accepted period. Use this table for historical breakdowns by age, ethnicity, gender or deprivation. The newest submitted record is used within each provider period, with conflicting records flagged. Differences between providers remain separate, and current cross-system demographics do not replace submitted history. IMD 2019 and IMD 2025 use fixed reference editions. Population access rates need an external population denominator.',
    referral_periods AS {{ ref('fct_mhsds_referral_period') }}
        PRIMARY KEY (referral_period_id) COMMENT = 'Referral state in each accepted submission. Each row is one referral and submission. A referral is open at period end if it was received by that date and has no rejection or discharge by that date. Attendance uses records whose contact date and reporting period are both no later than the selected period end. Later accepted corrections can revise historical results. An open referral with no attendance provides evidence of waiting, but does not establish eligibility for a national waiting list or target. Attendance follows the same referral ID when national person IDs change, with differences flagged. For demographic breakdowns, use the declared relationship to demographics for the same person, provider and period.',
    caseload_referrals AS {{ ref('fct_mhsds_current_caseload_referral') }}
        PRIMARY KEY (referral_period_id) COMMENT = 'Open referrals recorded in the dataset''s latest accepted month. Each row is one referral, including referrals awaiting first attendance and those receiving community or inpatient care. Providers whose latest submission is older are excluded here; their evidence remains in fct_mhsds_latest_provider_caseload_referral. Exclusion does not mean discharge. This is a monthly view of recorded open referrals, not a live list or a clinical judgement of active treatment. Eddie Davison owns the recorded-state definition. For demographic breakdowns, use the declared relationship to demographics for the same person, provider and period.',
    caseload_people AS {{ ref('fct_mhsds_current_caseload_person') }}
        PRIMARY KEY (caseload_person_provider_id) COMMENT = 'People with at least one recorded open referral in the dataset''s latest accepted month. Each row is one identifiable person and provider, with counts of open referrals and those without recorded attendance. Includes waiting, community and inpatient referrals. Count distinct person_id across providers because a person can appear at several providers. Open referrals without a person ID remain in fct_mhsds_current_caseload_referral. The table describes recorded caseload, not confirmed active treatment. Eddie Davison owns the definition. For demographic breakdowns, use the declared relationship to demographics for the same person, provider and period.',
    rtt AS {{ ref('fct_mhsds_referral_to_treatment_period') }}
        PRIMARY KEY (referral_to_treatment_period_id) COMMENT = 'Referral-to-treatment clocks reported by providers. Each row is one accepted MHS104 record in a reporting period, with the clock''s dates, measurement type and status. A submitted clock is different from the interval between referral and first recorded contact. Repeated period records remain present, so counts of populated start and end dates are counts of submitted evidence, not distinct clocks starting or ending. The specification allows earlier starts but expects submitted end dates within the reporting month. A missing end date does not prove the person is still waiting. Check date and status completeness by provider and period. The table does not decide national waiting-list eligibility or target compliance.',
    indirect_activity AS {{ ref('fct_mhsds_indirect_activity') }}
        PRIMARY KEY (indirect_activity_id) COMMENT = 'Care carried out for a patient without the patient being present. Each row is one accepted MHS204 record, with submitted duration, procedures, findings, professional and referral/team details from the same submission. Records from repeated reporting periods remain separate, so totals count submitted occurrences rather than proven distinct events across all time. Eddie Davison owns the definition. For demographic breakdowns, use the declared relationship to demographics for the same person, provider and period.',
    group_sessions AS {{ ref('fct_mhsds_group_session') }}
        PRIMARY KEY (group_session_id) COMMENT = 'Anonymous group sessions reported by providers. Each row is one accepted MHS301 session record in a reporting period. Participant numbers count participations, not distinct people. The source has no patient link, so this table cannot identify who attended. Do not add its participant totals to identified contact counts or infer links from dates, teams or sites.',
    group_therapy AS {{ ref('fct_mhsds_group_therapy_contact') }}
        PRIMARY KEY (group_therapy_contact_id) COMMENT = 'Patient contacts marked as group therapy by therapy mode 3 or the older group indicator Y. Each row is one latest referral/contact pair. Includes attendance, non-attendance and cancellation states; use is_attended for attended contacts. Missing person IDs remain present. The contacts have no shared session identifier, so they cannot establish exact session membership or be linked to anonymous MHS301 sessions. These contacts are already included in fct_mhsds_care_contact.',
    drop_ins AS {{ ref('fct_mhsds_drop_in_contact') }}
        PRIMARY KEY (drop_in_contact_id) COMMENT = 'Anonymous drop-in contacts reported by providers. Each row is one accepted MHS302 contact record in a reporting period. Demographic and outcome fields describe that contact. There is no national person ID or referral link, so this table cannot count distinct patients or link contacts into a person''s history.',
    accommodation AS {{ ref('fct_mhsds_accommodation_observation') }}
        PRIMARY KEY (accommodation_observation_id) COMMENT = 'Accommodation circumstances reported for patients. Each row is one accepted MHS003 record in a provider reporting period. Repeated reports remain present and do not represent new accommodation episodes. Older accommodation status and newer accommodation type are separate fields. Where the type field contains an older status code, the historical label is supplied and the label basis identifies that choice; no modern category is inferred. Unknown or unmatched values do not mean unsettled accommodation.',
    employment AS {{ ref('fct_mhsds_employment_observation') }}
        PRIMARY KEY (employment_observation_id) COMMENT = 'Employment circumstances reported for patients. Each row is one accepted MHS004 record in a provider reporting period. Includes employment status, its effective and recorded dates, contract type and weekly hours worked. Repeated submissions do not establish new jobs or changes in employment. Status descriptions use the general employment list and the mental-health extension; unmatched codes remain visible through the label-status field.',
    disability AS {{ ref('fct_mhsds_disability_observation') }}
        PRIMARY KEY (disability_observation_id) COMMENT = 'Disabilities and their perceived impact as reported for patients. Each row is one accepted MHS007 observation. Different disabilities and repeated provider-period reports remain separate. The reporting period does not establish when a disability began or its clinical severity.',
    social_circumstances AS {{ ref('fct_mhsds_social_circumstance_observation') }}
        PRIMARY KEY (social_circumstance_observation_id) COMMENT = 'Social and personal circumstances recorded for patients. Each row is one accepted MHS011 observation, with a description where the SNOMED code has a matching reference. Repeated submissions remain separate. The recorded date describes the observation; it does not establish the whole period during which the circumstance applied.',
    care_plans AS {{ ref('fct_mhsds_care_plan_period') }}
        PRIMARY KEY (care_plan_period_id) COMMENT = 'Care plans reported by providers in each accepted period. Each row is one MHS008 plan record in a reporting period. Creation, revision and implementation dates are kept separate. A plan record does not by itself confirm implementation or patient agreement; agreements are available in fct_mhsds_care_plan_agreement. For demographic breakdowns, use the declared relationship to demographics for the same person, provider and period.',
    care_plan_agreements AS {{ ref('fct_mhsds_care_plan_agreement') }}
        PRIMARY KEY (care_plan_agreement_id) COMMENT = 'Recorded agreements to care plans. Each row is one accepted MHS009 record, with agreement-party and family-involvement details. Several parties can agree to a plan, and repeated period reports remain separate. Missing agreement evidence does not mean disagreement.',
    complaints AS {{ ref('fct_mhsds_presenting_complaint') }}
        PRIMARY KEY (presenting_complaint_id) COMMENT = 'Symptoms and complaints recorded when people presented for care. Each row is one retained combination of provider, referral, person, coding scheme, code and recorded date. Records with incomplete identifying details remain separate. Descriptions use the submitted finding scheme, with case-sensitive Read v2 and CTV3 matches. Alternative-label fields show possible use of diagnosis-scheme numbering, but do not establish which interpretation is correct. A presenting complaint does not establish a formal or clinically current diagnosis.',
    assessment_instances AS {{ ref('fct_mhsds_assessment_instance') }}
        PRIMARY KEY (assessment_instance_id) COMMENT = 'Groups of responses that may belong to the same assessment. Each row groups a person, provider, tool, assessment context, recorded time and assessor, with referral, activity or source assessment identifiers where available. Referral and activity responses have no general questionnaire identifier, so responses recorded together can still be ambiguous. Undated responses without a source assessment ID stay separate. Counts and repeated-concept flags describe the recorded responses; they do not confirm questionnaire completion. Unmatched tools fall back to separate concept groups. HoNOS and SARN responses within one source clustering assessment form separate tool groups.',
    score_changes AS {{ ref('fct_mhsds_assessment_score_change') }}
        PRIMARY KEY (assessment_score_change_id) COMMENT = 'Changes between successive usable scores for the same person, provider, referral, assessment context, concept and recorded assessor. Each row pairs a current observation with its previous eligible observation. Records with missing dates, ambiguous same-time observations, invalid or non-score responses, or changed historical clustering person IDs are excluded before pairing; a pair can span those excluded records. Missing assessors form a separate group and do not prove the same clinician. Change is current score minus previous score. Its clinical direction depends on the instrument; it does not establish improvement or treatment effect.',
    ctos AS {{ ref('fct_mhsds_community_treatment_order') }}
        PRIMARY KEY (community_treatment_order_id) COMMENT = 'Recorded community treatment orders (CTOs). A CTO under section 17A of the Mental Health Act allows an eligible detained patient to leave hospital for treatment in the community under conditions, with a power of recall. Each row is one provider, legal-status period and order start date, using the latest accepted version. Renewals update expiry rather than create a new order. Recalls are recorded separately. An order is not an ordinary community referral or proof of continuous inpatient detention. A missing end date or future expiry alone does not establish current legal status. Incomplete identifying details retain separate source records.',
    recalls AS {{ ref('fct_mhsds_community_treatment_order_recall') }}
        PRIMARY KEY (community_treatment_order_recall_id) COMMENT = 'Returns to hospital for treatment under a community treatment order. Each row is one provider, legal-status period and recall start date/time, using the latest accepted version. Several recalls can occur during the same order and remain separate. The underlying order permits community treatment under conditions with a power of recall; the recall is a separate period. Missing times remain unknown, and incomplete identifying details retain separate source records.',
    restrictive_incidents AS {{ ref('fct_mhsds_restrictive_intervention_incident') }}
        PRIMARY KEY (restrictive_intervention_incident_id) COMMENT = 'Recorded incidents involving restrictive interventions. Each row is one incident identified within its provider, using its latest accepted version. An incident can have several intervention types in fct_mhsds_restrictive_intervention_type, so count incidents before joining those details. The table uses the version 6 MHS505 incident source and does not combine the retired intervention source. Records with incomplete identifying details remain separate.',
    restrictive_types AS {{ ref('fct_mhsds_restrictive_intervention_type') }}
        PRIMARY KEY (restrictive_intervention_type_id) COMMENT = 'Types of restrictive intervention recorded during incidents. Each row is one provider-qualified intervention occurrence using its latest accepted version. Several occurrences can belong to the same incident. Injury fields describe submitted evidence; a missing value does not mean there was no injury. Records with incomplete identifying details remain separate. Count incidents from the incident table, not from this table.',
    home_leave AS {{ ref('fct_mhsds_home_leave') }}
        PRIMARY KEY (home_leave_id) COMMENT = 'Recorded periods of home leave. Each row is one provider, ward stay and leave start date/time, using the latest accepted version. Records with incomplete identifying details remain separate. These are recorded leave periods, not a statement of current whereabouts. Different leave types are kept in separate tables and are not automatically deducted from inferred occupancy or bed-day counts.',
    leave AS {{ ref('fct_mhsds_leave_of_absence') }}
        PRIMARY KEY (leave_of_absence_id) COMMENT = 'Recorded periods of leave of absence. Each row is one provider, ward stay and leave start date/time, using the latest accepted version. Records with incomplete identifying details remain separate. These are recorded leave periods, not a statement of current whereabouts. Different leave types are kept in separate tables and are not automatically deducted from inferred occupancy or bed-day counts.',
    awol AS {{ ref('fct_mhsds_absence_without_leave') }}
        PRIMARY KEY (absence_without_leave_id) COMMENT = 'Recorded periods of absence without leave. Each row is one provider, ward stay and leave start date/time, using the latest accepted version. Records with incomplete identifying details remain separate. These are recorded leave periods, not a statement of current whereabouts. Different leave types are kept in separate tables and are not automatically deducted from inferred occupancy or bed-day counts.',
    spell_commissioners AS {{ ref('fct_mhsds_spell_commissioner_period') }}
        PRIMARY KEY (spell_commissioner_period_id) COMMENT = 'Commissioner responsibility recorded during a hospital admission. Each row is one provider, spell, commissioner and assignment start date. Multiple or overlapping assignments remain included; the table does not choose one commissioner for the whole admission. It uses the latest accepted version of each assignment and preserves separate source records when identifying details are incomplete.',
    readiness AS {{ ref('fct_mhsds_discharge_readiness_period') }}
        PRIMARY KEY (discharge_readiness_period_id) COMMENT = 'Periods when a patient was recorded as clinically ready for discharge, with the reported reason for delay. Each row is one provider, hospital spell, readiness start date and delay reason. A changed reason can start another period. The end date can mean the patient stopped being ready without being discharged. Duration is the difference between recorded dates, not a count of delayed occupied bed days. The latest accepted version is used; records with incomplete identifying details remain separate.',
    ward_capacity AS {{ ref('fct_mhsds_ward_capacity_period') }}
        PRIMARY KEY (ward_capacity_period_id) COMMENT = 'Reported ward capacity alongside recorded ward-stay evidence. Each row is one ward in an accepted submission. Available bed days include staffed beds whether occupied or unoccupied; temporarily closed bed days are separate. Their sum gives the reported bed base only when both are supplied. Dividing by the days in the period gives average beds, not physical bed stock or availability at month end or now. Capacity fields were introduced in MHSDS version 6 from April 2024; earlier ward details do not report capacity. Recorded stay midnights use ward stays from the same submission and include leave, with missing-date and overlap flags. Their ratio to available bed days is descriptive, not a validated occupancy rate. This commissioning extract may cover fewer patients than the whole ward''s capacity.',
    latest_provider_caseload AS {{ ref('fct_mhsds_latest_provider_caseload_referral') }}
        PRIMARY KEY (referral_period_id) COMMENT = 'Open referrals from each provider''s latest accepted reporting period. Each row is one referral received by period end with no rejection or discharge by that date. Includes referrals without an attended contact, with no inactivity cut-off. Provider periods can differ or be old; use the lag fields when comparing providers. Use fct_mhsds_current_caseload_referral for a common dataset-latest month. Referrals absent from a provider''s latest submission are neither carried forward nor declared discharged. Join team relationships using both submission and referral; several teams may match. Eddie Davison owns the definition.'
)

