DIMENSIONS(
    people.person_id AS person_id COMMENT = 'MHSDS person identifier for linking aggregate cohorts. National matching changes can give one individual several IDs. Never return person identifiers in query results.',
    people.sk_patient_id AS sk_patient_id COMMENT = 'Pseudonymised cross-system patient identifier; null when no bridge match exists. Reduce each dataset to the intended cohort grain before linking. Return aggregates only.',
    people.as_of_date AS as_of_date COMMENT = 'Latest accepted dataset reporting-period end. Use as the observation date for current person measures; it is not the run date and providers can have older evidence.',
    people.person_last_evidence_date AS last_evidence_reporting_period_end_date COMMENT = 'Latest reporting-period end among this person''s modelled evidence. Describes when evidence was submitted, not the latest date of care.',
    people.is_current_inpatient AS is_current_inpatient COMMENT = 'True if the person has a retained open inpatient interval after shared overlap rules. An undischarged spell must have been reported within two calendar months of the latest staged spell period. It is not live occupancy.',
    people.is_currently_detained AS is_currently_detained COMMENT = 'True when a recorded detention period has no end date, no expiry before as_of_date, and was reported within two calendar months of as_of_date. False means no qualifying evidence, not proof of no detention.',
    people.has_recorded_detention AS has_recorded_detention COMMENT = 'True if any retained legal-status record is classified as detention. Describes the available history, not lifetime completeness or current detention.',
    people.is_looked_after_child AS is_looked_after_child COMMENT = 'Latest reported looked-after-child indicator: Y gives true, N gives false, other or missing values give null. Null must not be treated as no.',
    people.has_primary_diagnosis_evidence AS n_primary_diagnosis_records > 0 COMMENT = 'True if any retained primary diagnosis evidence exists for the person. Does not identify a clinically current diagnosis.',
    people.has_recent_attended_contact AS n_attended_contacts_12m > 0 COMMENT = 'True if an attended contact falls between as_of_date minus 12 calendar months and as_of_date, including both dates. Later contacts are excluded.',
    referrals.referrals_provider_code AS provider_organisation_code COMMENT = 'Code of the provider reporting these referrals. Use for provider comparisons; codes are more stable grouping keys than names.',
    referrals.referrals_provider_name AS provider_organisation_name COMMENT = 'Name of the provider reporting these referrals. Use for provider comparisons; a missing name does not mean the provider code is absent.',
    contacts.contacts_provider_code AS provider_organisation_code COMMENT = 'Code of the provider reporting these patient contacts. Use for provider comparisons; codes are more stable grouping keys than names.',
    contacts.contacts_provider_name AS provider_organisation_name COMMENT = 'Name of the provider reporting these patient contacts. Use for provider comparisons; a missing name does not mean the provider code is absent.',
    spells.spells_provider_code AS provider_organisation_code COMMENT = 'Code of the provider reporting these hospital spells. Use for provider comparisons; codes are more stable grouping keys than names.',
    spells.spells_provider_name AS provider_organisation_name COMMENT = 'Name of the provider reporting these hospital spells. Use for provider comparisons; a missing name does not mean the provider code is absent.',
    occupancy.occupancy_provider_code AS provider_organisation_code COMMENT = 'Code of the provider reporting these inpatient intervals. Use for provider comparisons; codes are more stable grouping keys than names.',
    occupancy.occupancy_provider_name AS provider_organisation_name COMMENT = 'Name of the provider reporting these inpatient intervals. Use for provider comparisons; a missing name does not mean the provider code is absent.',
    diagnoses.diagnoses_provider_code AS provider_organisation_code COMMENT = 'Code of the provider reporting these diagnoses. Use for provider comparisons; codes are more stable grouping keys than names.',
    diagnoses.diagnoses_provider_name AS provider_organisation_name COMMENT = 'Name of the provider reporting these diagnoses. Use for provider comparisons; a missing name does not mean the provider code is absent.',
    assessments.assessments_provider_code AS provider_organisation_code COMMENT = 'Code of the provider reporting these assessment responses. Use for provider comparisons; codes are more stable grouping keys than names.',
    assessments.assessments_provider_name AS provider_organisation_name COMMENT = 'Name of the provider reporting these assessment responses. Use for provider comparisons; a missing name does not mean the provider code is absent.',
    legal_status.legal_status_provider_code AS provider_organisation_code COMMENT = 'Code of the provider reporting these legal-status periods. Use for provider comparisons; codes are more stable grouping keys than names.',
    legal_status.legal_status_provider_name AS provider_organisation_name COMMENT = 'Name of the provider reporting these legal-status periods. Use for provider comparisons; a missing name does not mean the provider code is absent.',
    submissions.submissions_provider_code AS provider_organisation_code COMMENT = 'Code of the provider reporting these submissions. Use for provider comparisons; codes are more stable grouping keys than names.',
    submissions.submissions_provider_name AS provider_organisation_name COMMENT = 'Name of the provider reporting these submissions. Use for provider comparisons; a missing name does not mean the provider code is absent.',
    referrals.referral_received_date AS referral_received_date COMMENT = 'Date the service recorded receiving the referral. Use for referral-intake trends, not the submission reporting period.',
    referrals.recorded_referral_status AS referral_status COMMENT = 'Latest recorded status: rejected when a rejection date exists; otherwise closed when a discharge date exists; otherwise open. This does not evaluate dates at a historical month end. Use referral_periods for historical state and caseload_referrals for current monthly caseload.',
    referrals.referral_primary_team_type AS primary_service_or_team_type_description COMMENT = 'Type of the recorded primary referral team, where available. It is not the currency-selected service category or the full set of additional teams.',
    referrals.referral_reason AS primary_reason_for_referral_description COMMENT = 'Description of the primary reason recorded for the referral. Missing or unmatched codes have no label; do not infer a reason from diagnosis.',
    referrals.referral_priority AS clinical_response_priority_description COMMENT = 'Provider-recorded referral priority, such as routine or urgent where coded. This is the submitted category, not a calculated waiting-time target.',
    referrals.referral_age AS age_at_referral COMMENT = 'Age in years supplied for the referral. Source special or out-of-range values remain visible and must not be treated as ordinary ages.',
    contacts.contact_date AS care_contact_date COMMENT = 'Recorded date of the contact or scheduled appointment, including cancellations. Use this date for contact activity trends and filter attendance separately.',
    contacts.contact_team_type AS service_or_team_type_description COMMENT = 'Type of the team associated with this activity in its own submission. Use for service breakdowns; missing labels remain unknown.',
    contacts.contact_team_id AS service_or_team_id COMMENT = 'Provider-qualified identifier of the team resolved for the contact within its submission. Suitable for team grouping; names or types alone do not uniquely identify teams.',
    contacts.contact_team_attribution_basis AS service_or_team_attribution_basis COMMENT = 'How the contact team was chosen: explicit additional team, explicit older-style contact team, primary referral team for version 6 without an explicit team, or unresolved. An unmatched explicit team is not replaced.',
    contacts.contact_referral_received_date AS same_submission_referral_received_date COMMENT = 'Referral receipt date in the contact''s own submission. Use for historical contact context rather than a later revised referral date.',
    contacts.contact_same_submission_referral_linked AS is_same_submission_referral_linked COMMENT = 'True when the contact''s referral exists in the same accepted submission. False means the historical parent record is absent; the contact remains included.',
    contacts.contact_same_submission_person_consistent AS is_same_submission_referral_person_consistent COMMENT = 'Whether contact and referral person IDs agree within the same submission. Null means an identity is missing. A false value is a conflict to inspect, not permission to reassign the contact.',
    contacts.contact_latest_referral_person_consistent AS is_latest_referral_person_consistent COMMENT = 'Whether the contact person ID agrees with the latest referral version. False can result from a later national ID change even when the original same-submission records agreed.',
    referrals.referral_has_contact_person_disagreement AS has_contact_referral_person_disagreement COMMENT = 'True if at least one contact person ID differs from the latest referral person ID. Contact counts and first-attendance intervals still follow the stable referral key.',
    contacts.contact_attendance AS attendance_status_description COMMENT = 'Provider-recorded attendance category. Use to distinguish attendance, non-attendance and cancellation before interpreting contact counts as delivered care.',
    contacts.is_attended AS is_attended COMMENT = 'True for attendance codes 05 or 06. Missing attendance gives null, not false. Use the attended-contact metric for delivered-contact counts under this definition.',
    contacts.contact_medium AS consultation_mechanism_description COMMENT = 'Recorded delivery method, such as face to face or telephone where coded. Missing or unmatched values have no label.',
    contacts.contact_age AS age_at_care_contact COMMENT = 'Age in years supplied for the contact. Source special or out-of-range values remain visible; do not treat them as ordinary ages.',
    spells.recorded_admission_date AS admission_date COMMENT = 'Recorded admission date for the hospital spell. Use for admission trends; the reporting period is a different date.',
    spells.recorded_discharge_date AS discharge_date COMMENT = 'Recorded hospital discharge date. Null means no discharge was recorded, not proof of a current inpatient stay. Use occupancy for inferred current state.',
    occupancy.occupancy_admission_date AS admission_date COMMENT = 'Recorded admission date of the retained occupancy interval. Use for starts of inferred inpatient intervals, not a raw count of provider-recorded admissions.',
    occupancy.occupancy_end_date AS occupancy_end_date COMMENT = 'End of the retained occupancy interval after recorded discharge, stale-submission and overlap rules. Null means the interval remains open under those rules.',
    occupancy.occupancy_end_reason AS occupancy_end_reason COMMENT = 'Reason the interval ended or remains open: recorded discharge, inferred last-submission closure, a later admission superseding it, or open. Use to distinguish recorded events from inferred dates.',
    occupancy.occupancy_is_current AS is_current_inpatient COMMENT = 'True if this retained interval remains open after overlap and recency rules. Stale undischarged spells are inferred closed; current evidence must be within two calendar months of the latest staged spell period.',
    occupancy.occupancy_evidence_date AS occupancy_evidence_as_of_date COMMENT = 'Latest reporting-period end in staged hospital spells, used as the occupancy freshness anchor. It can differ from the latest period of the wider MHSDS dataset.',
    diagnoses.diagnosis_role AS diagnosis_role COMMENT = 'Whether the diagnosis was recorded as previous, provisional, primary or secondary. A primary diagnosis is not automatically the current diagnosis.',
    diagnoses.diagnosis_code AS diagnosis_code COMMENT = 'Submitted diagnosis code. Always interpret with diagnosis_scheme; the same text can mean different things in different coding systems.',
    diagnoses.diagnosis_description AS diagnosis_description COMMENT = 'Reference label for the submitted diagnosis code and scheme, when matched. Null does not mean no diagnosis was recorded.',
    diagnoses.diagnosis_scheme AS coding_scheme_description COMMENT = 'Coding system declared for this diagnosis. Keep it with diagnosis_code when filtering or grouping codes.',
    diagnoses.diagnosis_recorded_at AS diagnosis_recorded_at COMMENT = 'Recorded diagnosis time, or discussion time for previous diagnoses. Use for recorded-evidence trends; it is not necessarily onset and does not establish current clinical status.',
    assessments.assessment_concept_code AS assessment_concept_code COMMENT = 'Code for the assessment question, dimension or score. Select a single concept before interpreting or averaging numeric scores.',
    assessments.assessment_concept_description AS assessment_concept_description COMMENT = 'Reference label for the assessment question, dimension or score. Different concepts from the same tool can measure different things.',
    assessments.assessment_tool AS assessment_tool_name COMMENT = 'Assessment instrument identified by the maintained response definitions. Null means the instrument was not matched. Tool name alone is insufficient for pooling different score concepts.',
    assessments.assessment_recorded_at AS assessment_recorded_at COMMENT = 'Date/time attributed to the recorded assessment response. Referral responses use their recorded time, activity responses can inherit same-submission activity time, and historical clustering responses use the matching assessment completion record. Missing time is not invented.',
    assessments.assessment_response_status AS assessment_response_status COMMENT = 'Whether the response matches a defined score, a recognised non-score response or an unmatched/missing reference state. Use scored_observation_count for interpreted numeric values; an observation is not a completed questionnaire.',
    legal_status.legal_status_description AS legal_status_description COMMENT = 'Reference description of the submitted Mental Health Act legal status. Missing labels remain unknown and do not establish informal status.',
    legal_status.legal_status_start_date AS legal_status_start_date COMMENT = 'Recorded start of the legal-status period. Use for period-start trends, not as the observation date of current detention.',
    legal_status.is_detention_period AS is_detention_period COMMENT = 'True for the maintained formal-detention codes. Informal status 01, guardianship 35/36, not-applicable 98, unknown 99 and unrecognised codes are not classified as detention.',
    legal_status.is_current_detention_period AS is_current_detention_period COMMENT = 'True when the period is classified as detention, has no end date, is not expired at the latest dataset period, and was last reported within two calendar months of that date. This is feed-based evidence, not a live legal-status check.',
    submissions.submission_period_end AS reporting_period_end_date COMMENT = 'End of the accepted provider reporting period. Use for submission coverage and freshness, not dates of care.',
    submissions.is_latest_provider_period AS is_latest_provider_period COMMENT = 'True for a provider''s latest accepted reporting period. Filter true before comparing provider lag; providers can have different latest periods.',
    submissions.provider_months_behind_dataset AS provider_months_behind_dataset COMMENT = 'Calendar months between the provider''s latest accepted period and the dataset latest period. Zero means aligned with this feed, not necessarily with today. A gap alone does not prove a failed submission.',
    demographics.demographics_provider_code AS provider_organisation_code COMMENT = 'Code of the provider reporting these demographic snapshots. Use for provider comparisons; codes are more stable grouping keys than names.',
    demographics.demographics_provider_name AS provider_organisation_name COMMENT = 'Name of the provider reporting these demographic snapshots. Use for provider comparisons; a missing name does not mean the provider code is absent.',
    demographics.demographics_period_end AS reporting_period_end_date COMMENT = 'End of the accepted reporting period described by this snapshot. Select one period for a point-in-time comparison; summing periods repeats the underlying people, referrals or wards.',
    demographics.demographics_ethnicity AS ethnicity_2001_description COMMENT = 'Ethnicity recorded for this person, provider and reporting period, labelled using the NHS Census 2001 categories. Use only through the supported period-demographic relationship.',
    demographics.demographics_gender_identity AS gender_identity_description COMMENT = 'Gender identity recorded for this person, provider and period. This is distinct from the older person-stated-gender field; null remains unknown.',
    demographics.demographics_imd_2019_decile AS residence_imd_2019_decile COMMENT = 'IMD 2019 decile for the recorded residence area: 1 is most deprived and 10 least deprived. The reference edition is fixed; it does not measure individual deprivation or change annually.',
    demographics.demographics_imd_2025_decile AS residence_imd_2025_decile COMMENT = 'IMD 2025 decile for the recorded residence area: 1 is most deprived and 10 least deprived. Applying it to earlier care is a retrospective area classification, not deprivation measured in that earlier year.',
    demographics.demographics_age_at_period_end AS source_age_at_period_end COMMENT = 'Age in years reported at the end of this person/provider period. Special or out-of-range source values remain visible and should be excluded from ordinary age bands.',
    referral_periods.referral_periods_provider_code AS provider_organisation_code COMMENT = 'Code of the provider reporting these referral-period records. Use for provider comparisons; codes are more stable grouping keys than names.',
    referral_periods.referral_periods_provider_name AS provider_organisation_name COMMENT = 'Name of the provider reporting these referral-period records. Use for provider comparisons; a missing name does not mean the provider code is absent.',
    referral_periods.referral_periods_period_end AS reporting_period_end_date COMMENT = 'End of the accepted reporting period described by this snapshot. Select one period for a point-in-time comparison; summing periods repeats the underlying people, referrals or wards.',
    referral_periods.referral_periods_access_state AS recorded_access_state COMMENT = 'Referral state at period end: receipt date missing, not started, rejected, discharged, attended contact recorded, or no attended contact recorded. State follows that period''s referral and attendance evidence.',
    referral_periods.referral_periods_open_at_period_end AS is_recorded_open_at_period_end COMMENT = 'True if the referral was received by period end and has no rejection or discharge by that date. Missing receipt can leave this unknown. Select one period when counting open referrals.',
    referral_periods.referral_periods_waiting_for_first_attendance AS is_open_without_recorded_attendance COMMENT = 'True for an open referral with no attended contact evidenced by period end. This is evidence of waiting for first attendance, not national waiting-list eligibility.',
    referral_periods.referral_periods_primary_team AS primary_service_or_team_type_description COMMENT = 'Type of the recorded primary referral team, where available. It is not the currency-selected service category or the full set of additional teams.',
    caseload_referrals.caseload_referrals_provider_code AS provider_organisation_code COMMENT = 'Code of the provider reporting these open referrals. Use for provider comparisons; codes are more stable grouping keys than names.',
    caseload_referrals.caseload_referrals_provider_name AS provider_organisation_name COMMENT = 'Name of the provider reporting these open referrals. Use for provider comparisons; a missing name does not mean the provider code is absent.',
    caseload_referrals.caseload_referrals_period_end AS reporting_period_end_date COMMENT = 'Dataset latest accepted month used for this current caseload. Use as the observation date, not the run date or referral receipt date.',
    caseload_referrals.caseload_referrals_contact_state AS recorded_caseload_contact_state COMMENT = 'Distinguishes open referrals with no attendance, attendance in the provider''s latest period, or attendance only in an earlier period. No inactivity cut-off removes referrals.',
    caseload_referrals.caseload_referrals_provider_months_behind AS provider_months_behind_dataset COMMENT = 'Provider lag relative to the dataset latest period. This current-month table restricts providers to that period, so lag is zero; use latest_provider_caseload to inspect older providers.',
    caseload_referrals.caseload_referrals_primary_team AS primary_service_or_team_type_description COMMENT = 'Type of the recorded primary referral team, where available. It is not the currency-selected service category or the full set of additional teams.',
    caseload_people.caseload_people_provider_code AS provider_organisation_code COMMENT = 'Code of the provider reporting these people with open referrals. Use for provider comparisons; codes are more stable grouping keys than names.',
    caseload_people.caseload_people_provider_name AS provider_organisation_name COMMENT = 'Name of the provider reporting these people with open referrals. Use for provider comparisons; a missing name does not mean the provider code is absent.',
    caseload_people.caseload_people_evidence_date AS evidence_date COMMENT = 'Dataset latest accepted reporting-period end used for this current person/provider caseload. All rows use this month; it is not the run date.',
    caseload_people.caseload_people_provider_months_behind AS provider_months_behind_dataset COMMENT = 'Provider lag relative to the dataset latest period. This current-month table has zero lag; this does not mean the feed is current to today.',
    rtt.rtt_provider_code AS provider_organisation_code COMMENT = 'Code of the provider reporting these RTT clocks. Use for provider comparisons; codes are more stable grouping keys than names.',
